        default_vvp_instance = alicloud.realtimecompute.VvpInstance("default",
            vvp_instance_name=name,
            storage={
                "oss": {
                    "bucket": default_bucket.id,
                },
            },
            vpc_id=default.id,
            vswitch_ids=[default_switch.id],
            resource_spec={
                "cpu": 4,
                "memory_gb": 16,
            },
            payment_type="PayAsYouGo",
            zone_id=default_switch.zone_id)
        default_sql_file = alicloud.realtimecompute.SqlFile("default",
            workspace=default_vvp_instance.resource_id,
            namespace=default_vvp_instance.vvp_instance_name.apply(lambda vvp_instance_name: f"{vvp_instance_name}-default"),
            name=name,
            sql_script="SELECT * FROM `vvp`.`default`.example_table;",
            session_cluster_name="example-session-cluster",
            description="example sql file")
